// Source: src/core/runtime.js
'use strict';
const $=s=>document.querySelector(s);
const icons={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',send:'M22 2L9 15M22 2l-7 20-6-7-7-6z',card:'M3 5h18v14H3zM3 9h18M7 15h3',loan:'M3 21h18M5 21V9m5 12V9m4 12V9m5 12V9M2 9l10-6 10 6z',history:'M3 12a9 9 0 1 0 3-7M3 3v5h5m4 0v5l3 2',arrow:'M7 17L17 7M7 7h10v10',down:'M7 7l10 10M7 17h10V7',check:'M5 12l4 4L19 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',logout:'M9 4H4v16h5M13 8l4 4-4 4m-6-4h14',wallet:'M3 6h17v14H3zM3 6V4h15v2m-2 6h6v4h-6z',file:'M6 2h8l5 5v15H6zM14 2v6h5M9 12h7m-7 4h7',plus:'M12 5v14M5 12h14',shield:'M12 2L3 6v6c0 6 9 10 9 10s9-4 9-10V6zM8 12l3 3 5-6',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',snow:'M12 2v20M3 7l18 10M3 17L21 7M9 4l3 3 3-3M9 20l3-3 3 3',help:'M9 8a3 3 0 1 1 4 3c-1 .5-1 1-1 3m0 3v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevron:'M9 5l7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 22v-3a8 8 0 0 1 16 0v3'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`}
const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<div class="brand"><span class="brand-mark">b.</span><span>Bimi<span class="brand-sub">ProCredit-inspired concept</span></span></div>`;
const seed=()=>({name:'Era Krasniqi',email:'demo@bimi.test',balance:8420.5,savings:12500,card:{frozen:false,online:true,contactless:true,international:false,atm:500,pos:1500,web:750},loans:[],tx:[{id:'DEMO-1042',name:'Monthly salary',desc:'Incoming transfer',amount:1850,date:'2026-10-21',kind:'in'},{id:'DEMO-1041',name:'Meridian Express',desc:'Card payment · Prishtina',amount:-48.6,date:'2026-10-21',kind:'card'},{id:'DEMO-1040',name:'KESCO',desc:'Electricity bill',amount:-62.4,date:'2026-10-20',kind:'out'},{id:'DEMO-1039',name:'Arben Berisha',desc:'Domestic transfer',amount:-120,date:'2026-10-19',kind:'out'},{id:'DEMO-1038',name:'Soma Book Station',desc:'Card payment · Prishtina',amount:-18.5,date:'2026-10-18',kind:'card'}]});
let state;try{state=JSON.parse(sessionStorage.getItem('bimi-demo-v2'))||seed()}catch{state=seed()}
let logged=false,page='dashboard',authTab='login',authStep=0,registration={},registeredCredentials=null,transfer=null,transferStage=0,loanStage=0,loan={amount:10000,months:36,purpose:'Home improvement',income:1850,commitments:200,employment:'Employed',docs:false},cardReveal=false,showSchedule=false;
function save(){try{sessionStorage.setItem('bimi-demo-v2',JSON.stringify(state))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function reference(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase()}
function dateText(d){return new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function error(t){const el=$('#form-error');if(el){el.textContent=t;el.classList.remove('hidden');el.scrollIntoView({block:'nearest'})}else toast(t)}
function goto(p){page=p;transferStage=0;transfer=null;render();window.scrollTo(0,0)}

// Source: src/features/auth-base.js
function baseAuth(){return `<div class="auth"><section class="auth-story">${brand()}<h1>Your money.<br>Your possibilities.</h1><p>A simpler way to bank, from everyday payments to your next big step.</p>${bankcard(false,true)}<div class="row" style="color:#c8ddba">${icon('shield')}<span>One connected banking experience.</span></div><div class="auth-foot">Independent concept inspired by modern Kosovo banking.<br>Not affiliated with ProCredit Bank. Fictional data only.</div></section><section class="auth-main"><div class="auth-box">${brand()}<span class="tag">INTERACTIVE DEMO</span><div class="auth-tabs"><button class="${authTab==='login'?'active':''}" onclick="switchAuth('login')">Log in</button><button class="${authTab==='register'?'active':''}" onclick="switchAuth('register')">Register</button></div>${authTab==='login'?loginForm():authTab==='reset'?resetForm():registerForm()}<div class="notice">${icon('shield')} Use fictional details only. This prototype does not create a bank account or connect to real banking services.</div></div></section></div>`}
function loginForm(){return `<h2>Welcome back.</h2><p class="muted">Your everyday banking, all in one place.</p><form id="login-form"><label>Email address<input type="email" name="email" value="demo@bimi.test" autocomplete="off" required></label><label>Demo password<input type="password" name="password" value="Bimi2026!" autocomplete="off" required></label><div class="row between"><span class="fieldhelp">Demo credentials are prefilled.</span><button type="button" class="textbtn" onclick="switchAuth('reset')">Forgot password?</button></div><div id="form-error" class="error hidden" role="alert"></div><button class="btn" type="submit">Log in securely ${icon('chevron')}</button></form><div class="demo-entry"><h3>Take a look around</h3><p>Explore all journeys with a fictional customer profile.</p><button class="btn secondary" onclick="enterDemo()">Explore demo ${icon('arrow')}</button></div>`}
function resetForm(){return `<h2>Reset demo access</h2><p class="muted">No email is sent. Restore the sample login below.</p><div class="demo-entry"><h3>Sample credentials</h3><p>demo@bimi.test<br>Bimi2026!</p><button class="btn" onclick="registeredCredentials=null;switchAuth('login');toast('Sample login restored. No email was sent.')">Back to login</button></div>`}
function switchAuth(t){authTab=t;authStep=0;render()}
function registerForm(){if(authStep===1)return `<h2>Verify your mobile</h2><p class="muted">Simulated verification for ${esc(registration.phone)}.</p><form id="register-verify"><div class="notice">No SMS was sent. Enter demo code <strong>123456</strong>.</div><label>Verification code<input name="code" pattern="[0-9]{6}" inputmode="numeric" maxlength="6" required placeholder="6-digit code"></label><div id="form-error" class="error hidden" role="alert"></div><button class="btn" type="submit">Verify & activate demo ${icon('check')}</button><button class="btn secondary" type="button" onclick="authStep=0;render()">Back</button></form>`;
return `<h2>Start your journey.</h2><p class="muted">Create a temporary demo profile in two simple steps.</p><form id="register-form"><div class="formgrid"><label>First name<input name="first" value="Era" required maxlength="35" autocomplete="off"></label><label>Last name<input name="last" value="Krasniqi" required maxlength="35" autocomplete="off"></label></div><label>Fictional email address<input name="email" type="email" required placeholder="era@example.test" autocomplete="off"></label><label>Sample phone number<input name="phone" type="tel" required value="+383 44 000 000" autocomplete="off"></label><label>Demo password<input name="password" type="password" minlength="8" required placeholder="At least 8 characters" autocomplete="off"></label><label class="check"><input type="checkbox" required><span>I understand this is a demonstration. Identity verification and account opening are simulated.</span></label><div id="form-error" class="error hidden" role="alert"></div><button type="submit" class="btn">Continue ${icon('chevron')}</button></form>`}
function enterDemo(){logged=true;page='dashboard';render();window.scrollTo(0,0)}

// Source: src/core/shell-base.js
function baseShell(){const nav=[['dashboard','home','Overview'],['transfers','send','Transfers'],['cards','card','Cards'],['loans','loan','Loans'],['activity','history','Activity']];return `<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">YOUR BANKING</div><nav class="nav" aria-label="Main navigation">${nav.map(([p,i,n])=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="goto('${p}')">${icon(i)}${n}${p==='loans'?'<span class="badge">NEW</span>':''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="row">${icon('shield')}<strong style="font-size:12px">Built around you</strong></div><p>Explore freely.<br>Every transaction is simulated.</p><div class="divider" style="background:#ffffff20"></div><button class="textbtn" style="color:#cadbce" onclick="logout()">${icon('logout')} Log out</button></div></aside><div class="workspace"><header class="topbar"><div class="row"><span class="breadcrumb muted">Personal banking <span style="padding:0 13px;color:#b3beb2">/</span> <strong style="color:var(--ink)">${nav.find(n=>n[0]===page)?.[2]||'Overview'}</strong></span><span class="tag">DEMO</span></div><div class="row"><button class="profile-btn" aria-label="Notifications" onclick="toast('You are up to date. Demo notifications will appear after transfers and loan disbursement.')">${icon('bell')}</button><span style="height:24px;border-left:1px solid var(--line);margin:0 8px"></span><div class="avatar">${esc(state.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div class="profile"><strong>${esc(state.name)}</strong><div class="muted">Personal account</div></div><button class="profile-btn" onclick="logout()" aria-label="Log out">${icon('logout')}</button></div></header><main class="main" id="main">${page==='dashboard'?dashboard():page==='transfers'?transfers():page==='cards'?cards():page==='loans'?loans():activity()}<footer class="footer"><span>© 2026 Bimi. Independent banking concept · Not affiliated with ProCredit Bank.</span><span>Fictional data · No real payments or signatures</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([p,i,n])=>`<button class="${page===p?'active':''}" onclick="goto('${p}')">${icon(i)}${n==='Overview'?'Home':n}</button>`).join('')}</nav></div>`}
function logout(){logged=false;authTab='login';authStep=0;render()}
function render(){document.getElementById('root').innerHTML=logged?shell():auth();bind();}
function pagehead(title,sub,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function bankcard(frozen=false,authCard=false){return `<div class="bankcard ${frozen?'frozen':''}"><div class="row between"><strong style="font-size:18px;letter-spacing:-.5px">Bimi</strong>${icon('wallet')}</div><div class="cardnum">${cardReveal&&!authCard?'9999 0000 0000 4821':'•••• &nbsp; •••• &nbsp; •••• &nbsp; 4821'}</div><div class="row between"><div><div class="eyebrow">${authCard?'ERA KRASNIQI':esc(state.name.toUpperCase())}</div><small>${frozen?'FROZEN':'DEBIT'} <span style="margin-left:10px">12/29</span></small></div><div class="mastercard" aria-label="Illustrative payment card"></div></div></div>`}
function baseTxRows(list){return list.length?list.map(t=>`<div class="tx"><div class="roundicon">${icon(t.kind==='in'?'down':t.kind==='card'?'card':'send')}</div><div><strong>${esc(t.name)}</strong><small>${esc(t.desc)}</small></div><div class="txvalue ${t.amount>0?'in':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}<small>${dateText(t.date)}</small></div></div>`).join(''):'<div class="empty">No transactions match your search.</div>'}
function baseDashboard(){const total=state.balance+state.savings;return `${pagehead('A little more possibility.','Welcome back, '+esc(state.name.split(' ')[0])+'. Here’s your money at a glance.',`<button class="btn" onclick="goto('transfers')">${icon('plus')} New transfer</button>`)}<div class="dashgrid"><div class="stack"><div><div class="stats"><section class="panel balance"><div class="row between"><span class="eyebrow">Everyday account</span><span class="pill">● Active</span></div><div class="amount">${money(state.balance)}</div><div class="muted" style="font-size:12px">Available balance</div><div class="row between" style="margin-top:25px"><span class="accountno">XK05 0000 0000 0000 0000 <small>· DEMO</small></span>${icon('wallet')}</div></section><section class="panel"><div class="row between"><span class="eyebrow muted">Savings</span><div class="roundicon">${icon('wallet')}</div></div><div class="savingamount">${money(state.savings)}</div><p class="muted" style="font-size:12px">Your next chapter starts here.</p><div class="divider" style="margin:18px 0 12px"></div><div class="row between"><small class="muted">Total across accounts</small><strong style="font-size:12px">${money(total)}</strong></div></section></div><div class="quick-actions"><button onclick="goto('transfers')">${icon('send')}Send money</button><button onclick="goto('cards')">${icon('card')}Manage card</button><button onclick="startLoan()">${icon('loan')}Apply for a loan</button><button onclick="statement()">${icon('download')}Statement</button></div></div><section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><small class="muted">Your latest money movements</small></div><button class="textbtn" onclick="goto('activity')">View all ${icon('chevron')}</button></div>${txRows(state.tx.slice(0,5))}</section><div class="panel insight"><div class="row between"><div><span class="eyebrow muted">Made for everyday</span><h2 style="margin-top:7px">Less admin. More living.</h2><p style="margin-bottom:0">Payments, cards and your next loan — together in one place.</p></div><div class="roundicon">${icon('shield')}</div></div></div></div><aside class="stack dash-aside"><section class="panel"><div class="panel-head"><h2>Your card</h2><span class="pill ${state.card.frozen?'warn':''}">${state.card.frozen?'Frozen':'Active'}</span></div>${bankcard(state.card.frozen)}<div class="metric"><span class="muted">Online payment limit</span><strong>${money(state.card.web)} / day</strong></div><button class="btn secondary" style="width:100%;margin-top:9px" onclick="goto('cards')">Manage card ${icon('settings')}</button></section><section class="panel insight"><div class="roundicon">${icon('loan')}</div><h2 style="margin-top:15px">Make your next move.</h2><p>Explore a personal loan with clear costs and a monthly payment that works for you.</p><div class="row between" style="margin-bottom:18px"><small>Illustrative fixed interest</small><strong>6.90% p.a.</strong></div><button class="btn" style="width:100%" onclick="startLoan()">Explore loans ${icon('arrow')}</button></section>${state.loans.length?`<section class="panel"><h3>Your active demo loan</h3><div class="hero-number">${money(state.loans.at(-1).payment)}</div><small class="muted">Monthly instalment · ${state.loans.at(-1).months} months</small><button class="textbtn" style="display:block;margin-top:12px" onclick="goto('loans')">View loan details →</button></section>`:''}</aside></div>`}

// Source: src/features/transfers-base.js
function transferSummary(t){return `<div class="summary-line"><span>Recipient</span><strong>${esc(t.name)}</strong></div><div class="summary-line"><span>Account</span><strong style="word-break:break-all">${esc(t.iban)}</strong></div><div class="summary-line"><span>Transfer type</span><strong>${esc(t.type)}</strong></div><div class="summary-line"><span>Amount</span><strong>${money(t.amount)}</strong></div><div class="summary-line"><span>Transfer fee</span><strong>${money(t.fee)}</strong></div><div class="summary-line"><span>Total debit</span><strong>${money(t.amount+t.fee)}</strong></div><div class="summary-line"><span>Reference</span><strong>${esc(t.note||'Personal transfer')}</strong></div>`}
function baseTransfers(){let content='';if(transferStage===0)content=`<div class="panel-head"><h2>Where are we sending?</h2><span class="pill">Step 1 of 3</span></div><form id="transfer-form" class="stack"><div class="formgrid"><label>Transfer type<select name="type"><option>Domestic transfer</option><option>Within Bimi</option></select></label><label>From account<select><option>Everyday account · ${money(state.balance)}</option></select></label><label class="wide">Recipient’s full name<input name="name" required maxlength="70" value="Arben Berisha" autocomplete="off"></label><label class="wide">Demo recipient IBAN<input name="iban" required value="XK05 0000 0000 0000 0001" autocomplete="off"><span class="fieldhelp">Fictional XK account format for this demo; no bank verification.</span></label><label>Amount (EUR)<input type="number" name="amount" min="0.01" step="0.01" required placeholder="0.00"></label><label>Payment reference<input name="note" maxlength="100" placeholder="What is it for?"></label></div><div class="notice">Domestic fee: €0.50. Within Bimi: €0.00. Demo transfers are completed immediately after confirmation.</div><div id="form-error" class="error hidden" role="alert"></div><button class="btn" style="justify-self:end" type="submit">Review transfer ${icon('chevron')}</button></form>`;
if(transferStage===1)content=`<div class="panel-head"><h2>Review your transfer</h2><span class="pill">Step 2 of 3</span></div>${transferSummary(transfer)}<div class="notice" style="margin-top:22px">Balance after transfer: <strong>${money(state.balance-transfer.amount-transfer.fee)}</strong>. Check the recipient and amount before continuing.</div><div class="formactions"><button class="btn secondary" onclick="transferStage=0;render()">Edit details</button><button class="btn" onclick="transferStage=2;render()">Continue to approval ${icon('lock')}</button></div>`;
if(transferStage===2)content=`<div class="panel-head"><h2>Approve your transfer</h2><span class="pill">Step 3 of 3</span></div><div class="loan-offer"><small class="muted">You are authorizing a simulated debit of</small><div class="hero-number">${money(transfer.amount+transfer.fee)}</div><p>To ${esc(transfer.name)} · ending ${esc(transfer.iban.slice(-4))}</p></div><form id="transfer-confirm" class="stack" style="margin-top:23px"><div class="notice">No SMS was sent. Use demo approval code <strong>123456</strong>.</div><label>Demo approval code<input name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required placeholder="6-digit code" autocomplete="off"></label><div id="form-error" class="error hidden" role="alert"></div><div class="formactions"><button type="button" class="btn secondary" onclick="transferStage=1;render()">Back</button><button class="btn" type="submit">Confirm ${money(transfer.amount+transfer.fee)} ${icon('check')}</button></div></form>`;
if(transferStage===3)content=`<div class="success"><div class="success-icon">${icon('check')}</div><span class="pill">Demo transfer completed</span><h2 style="margin-top:15px">Money on its way.</h2><p>${money(transfer.amount)} sent to ${esc(transfer.name)} in this demo. Your balance and activity have been updated.</p></div>${transferSummary(transfer)}<div class="summary-line"><span>Transaction ID</span><strong>${transfer.id}</strong></div><div class="formactions"><button class="btn secondary" onclick="receipt()">${icon('download')} Receipt</button><button class="btn" onclick="goto('dashboard')">Back to overview</button></div>`;
return `${pagehead('Move money, simply.','A clear view of every transfer, before you approve it.')}<div class="two-col"><section class="panel">${content}</section><aside class="stack"><section class="panel"><div class="row"><div class="roundicon">${icon('wallet')}</div><h3>Everyday account</h3></div><div class="hero-number">${money(state.balance)}</div><small class="muted">Available to transfer</small><div class="divider"></div><small class="muted">Demo account</small><p class="accountno" style="margin-top:7px">XK05 0000 0000 0000 0000</p></section><section class="panel insight"><h3>Know before you send</h3><div class="flow-list"><div class="flow-item"><span>1</span><div><strong>Enter the details</strong><small>Choose a recipient and amount.</small></div></div><div class="flow-item"><span>2</span><div><strong>Check the full cost</strong><small>Review the fee and total debit.</small></div></div><div class="flow-item"><span>3</span><div><strong>Approve securely</strong><small>Simulated code approval.</small></div></div></div></section></aside></div>`}
function receipt(){download('Bimi_Demo_Transfer_Receipt.txt',`BIMI — DEMO TRANSFER RECEIPT\nNot a real payment confirmation.\n\nReference: ${transfer.id}\nRecipient: ${transfer.name}\nDemo IBAN: ${transfer.iban}\nAmount: ${money(transfer.amount)}\nFee: ${money(transfer.fee)}\nTotal debit: ${money(transfer.amount+transfer.fee)}\nDate: ${localDate()}\nPayment reference: ${transfer.note||'Personal transfer'}`)}

// Source: src/features/cards-base.js
function baseCards(){const c=state.card;return `${pagehead('Your card. Your control.','Manage where and how your debit card can be used.')}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Card settings</h2><span class="pill ${c.frozen?'warn':''}">${c.frozen?'Card frozen':'Card active'}</span></div><div class="controlrow" style="padding-top:0"><div><strong>Freeze your card</strong><small>Simulate pausing all new card payments.</small></div><button class="btn ${c.frozen?'secondary':'danger'}" onclick="freezeCard()">${icon(c.frozen?'check':'snow')}${c.frozen?'Unfreeze':'Freeze card'}</button></div>${[['online','Online purchases','Allow payments on websites and in apps.'],['contactless','Contactless payments','Allow tap-to-pay purchases.'],['international','International use','Allow card purchases outside Kosovo.']].map(([key,title,desc])=>`<div class="controlrow"><div><strong>${title}</strong><small>${desc}</small></div><button role="switch" aria-checked="${c[key]}" aria-label="${title}" class="toggle ${c[key]?'on':''}" onclick="toggleCard('${key}')" ${c.frozen?'disabled':''}><span></span></button></div>`).join('')}<h3 style="margin:25px 0 18px">Daily spending limits</h3><form id="card-limits" class="stack"><div class="formgrid"><label>ATM withdrawals (EUR)<input name="atm" type="number" min="0" max="10000" step="1" value="${c.atm}" required></label><label>In-store purchases (EUR)<input name="pos" type="number" min="0" max="10000" step="1" value="${c.pos}" required></label><label>Online purchases (EUR)<input name="web" type="number" min="0" max="10000" step="1" value="${c.web}" required></label></div><small class="muted">Demo maximum: €10,000 per category per day. A limit of zero disables that category.</small><div id="form-error" class="error hidden" role="alert"></div><button class="btn" style="justify-self:end" type="submit">Save limits ${icon('check')}</button></form></section><aside class="stack"><section class="panel">${bankcard(c.frozen)}<button class="textbtn" style="width:100%;margin-top:14px" onclick="cardReveal=!cardReveal;render()">${icon('eye')} ${cardReveal?'Hide':'Show'} fictional card number</button><p class="legal">The number is a non-payment demo placeholder. No real card details are stored.</p><div class="divider"></div><div class="summary-line"><span>Card type</span><strong>Virtual demo debit</strong></div><div class="summary-line"><span>Linked account</span><strong>Everyday · EUR</strong></div><div class="summary-line"><span>Expires</span><strong>December 2029</strong></div></section><section class="panel insight"><div class="row">${icon('shield')}<h3>Stay in control</h3></div><p>These settings are saved for your current browser session. No request is sent to a card processor.</p></section></aside></div>`}
function freezeCard(){state.card.frozen=!state.card.frozen;save();render();toast(state.card.frozen?'Demo card frozen.':'Demo card unfrozen.')}
function toggleCard(key){state.card[key]=!state.card[key];save();render();toast('Demo card setting updated.')}

// Source: src/features/loans-base.js
function startLoan(){loanStage=0;page='loans';showSchedule=false;render();window.scrollTo(0,0)}
function loanCalc(l=loan){const p=Number(l.amount),n=Number(l.months),r=.069/12,payment=p*r/(1-Math.pow(1+r,-n)),fee=p*.01,net=p-fee,total=payment*n,interest=total-p;let lo=0,hi=1;for(let i=0;i<100;i++){const m=(lo+hi)/2,pv=payment*(1-Math.pow(1+m,-n))/m;if(pv>net)lo=m;else hi=m}return {payment,fee,net,total,interest,cost:interest+fee,apr:(Math.pow(1+(lo+hi)/2,12)-1)*100,ratio:(Number(l.commitments)+payment)/Number(l.income)*100}}
function loanSummary(){const c=loanCalc();return `<section class="panel"><div class="row between"><h3>Your loan at a glance</h3>${icon('loan')}</div><div class="hero-number" id="summary-payment">${money(c.payment)}<span style="font-size:12px;font-weight:400;letter-spacing:0"> / month</span></div><div class="summary-line"><span>Loan amount</span><strong id="summary-amount">${money(loan.amount)}</strong></div><div class="summary-line"><span>Term</span><strong id="summary-term">${loan.months} months</strong></div><div class="summary-line"><span>Fixed interest</span><strong>6.90% p.a.</strong></div><div class="summary-line"><span>Effective annual rate*</span><strong id="summary-apr">${c.apr.toFixed(2)}%</strong></div><div class="summary-line"><span>One-time fee (1%)</span><strong id="summary-fee">${money(c.fee)}</strong></div><div class="summary-line"><span>Net paid to account</span><strong id="summary-net">${money(c.net)}</strong></div><div class="summary-line"><span>Total instalments</span><strong id="summary-total">${money(c.total)}</strong></div><div class="summary-line"><span>Total borrowing cost*</span><strong id="summary-cost">${money(c.cost)}</strong></div><p class="legal">*Illustrative calculation includes a 1% fee deducted at disbursement. Equal monthly periods; rounding may affect the final instalment. No other fees or insurance assumed.</p></section>`}
function loanSteps(){return `<div class="steps" aria-label="Loan progress">${['Application','Documents','Assessment','Offer','Agreement','Sign','Complete'].map((s,i)=>`<div class="step ${i===loanStage?'current':i<loanStage?'done':''}" ${i===loanStage?'aria-current="step"':''}><div class="dot">${i<loanStage?'✓':i+1}</div>${s}</div>`).join('')}</div>`}
function baseLoans(){const c=loanCalc();let body='';if(loanStage===0)body=`<div class="panel-head"><div><span class="eyebrow muted">Personal loan</span><h2 style="margin-top:7px">Bring your plans to life.</h2></div><div class="roundicon">${icon('loan')}</div></div><form id="loan-application" class="stack"><div class="formgrid"><label>How much do you need? (EUR)<input id="loan-amount" name="amount" type="number" min="500" max="30000" step="100" required value="${loan.amount}"><span class="fieldhelp">€500–€30,000 · increments of €100</span></label><label>Repayment term<select id="loan-months" name="months">${[12,24,36,48,60,72,84].map(n=>`<option ${n===Number(loan.months)?'selected':''} value="${n}">${n} months</option>`).join('')}</select></label><label>Loan purpose<select name="purpose">${['Home improvement','Car purchase','Education','Personal expenses'].map(p=>`<option ${p===loan.purpose?'selected':''}>${p}</option>`).join('')}</select></label><label>Employment status<select name="employment">${['Employed','Self-employed','Other'].map(e=>`<option ${e===loan.employment?'selected':''}>${e}</option>`).join('')}</select></label><label>Net monthly income (EUR)<input name="income" type="number" min="1" max="1000000" step="0.01" required value="${loan.income}"></label><label>Existing monthly debt payments (EUR)<input name="commitments" type="number" min="0" max="1000000" step="0.01" required value="${loan.commitments}"></label></div><label class="check"><input name="consent" type="checkbox" required><span>I agree to a simulated affordability assessment using these fictional details.</span></label><div class="notice">Demo pricing is illustrative. An actual lending decision needs verified identity, income, credit information and bank approval.</div><div id="form-error" class="error hidden" role="alert"></div><button type="submit" class="btn" style="justify-self:end">Continue to documents ${icon('chevron')}</button></form>${state.loans.length?activeLoans():''}`;
if(loanStage===1)body=`<h2>A few things to confirm.</h2><p class="muted" style="margin:8px 0 22px">Use sample documents to explore the journey. Do not upload personal documents.</p><div class="upload"><div class="row between"><div><strong>Identity document</strong><small class="muted">Sample ID · fictional customer</small></div><span class="pill">Sample ready</span></div></div><div class="upload"><div class="row between"><div><strong>Proof of income</strong><small class="muted">Sample salary statement · last 3 months</small></div><span class="pill">Sample ready</span></div></div><form id="loan-documents" class="stack" style="margin-top:22px"><label class="check"><input type="checkbox" required><span>I understand these are sample documents. No real identity or income checks will be performed.</span></label><label class="check"><input type="checkbox" required><span>I confirm the demo income and existing debt payments entered are correct.</span></label><div class="formactions"><button type="button" class="btn secondary" onclick="loanStage=0;render()">Back</button><button class="btn" type="submit">Run demo assessment ${icon('shield')}</button></div></form>`;
if(loanStage===2){const pass=c.ratio<=40;body=`<div class="success"><div class="success-icon">${icon(pass?'check':'file')}</div><span class="pill ${pass?'':'warn'}">${pass?'Demo assessment passed':'Manual review needed'}</span><h2 style="margin-top:14px">${pass?'A good fit for your plans.':'Let’s take another look.'}</h2><p>${pass?'Your application meets the illustrative affordability threshold. Continue to review your demo offer.':'Your total monthly debt exceeds the demo threshold. Adjust the amount or term, or return to your application.'}</p></div><div class="summary-line"><span>Net monthly income</span><strong>${money(loan.income)}</strong></div><div class="summary-line"><span>Existing debt payments</span><strong>${money(loan.commitments)}</strong></div><div class="summary-line"><span>Proposed instalment</span><strong>${money(c.payment)}</strong></div><div class="summary-line"><span>Total debt / income</span><strong>${c.ratio.toFixed(1)}% · Demo threshold 40%</strong></div><div class="notice warning" style="margin-top:20px">Simulation only. No credit bureau, KYC, sanctions or fraud checks have been run. This is not a bank approval.</div><div class="formactions"><button class="btn secondary" onclick="loanStage=0;render()">Edit application</button>${pass?`<button class="btn" onclick="loanStage=3;render()">View my offer ${icon('chevron')}</button>`:''}</div>`}
if(loanStage===3)body=`<span class="eyebrow muted">Your illustrative offer</span><h2 style="margin:8px 0 22px">Clear terms. No surprises.</h2><div class="loan-offer"><span class="muted">${money(loan.amount)} over ${loan.months} months</span><div class="hero-number">${money(c.payment)} <small style="font-size:13px;font-weight:400;letter-spacing:0">/ month</small></div><div class="row between"><span>Fixed interest: 6.90% p.a.</span><span class="pill">EUR</span></div></div><div style="margin-top:16px"><div class="summary-line"><span>Interest across the term</span><strong>${money(c.interest)}</strong></div><div class="summary-line"><span>Fee deducted upfront</span><strong>${money(c.fee)}</strong></div><div class="summary-line"><span>Net amount you receive</span><strong>${money(c.net)}</strong></div><div class="summary-line"><span>Sum of instalments</span><strong>${money(c.total)}</strong></div><div class="summary-line"><span>Total cost (interest + fee)</span><strong>${money(c.cost)}</strong></div></div><button class="textbtn" onclick="showSchedule=!showSchedule;render()">${icon('file')} ${showSchedule?'Hide':'View'} repayment schedule</button>${showSchedule?schedule():''}<form id="loan-offer"><label class="check" style="margin-top:20px"><input type="checkbox" required><span>I have reviewed the payment, interest, fee and net disbursement in this illustrative offer.</span></label><div class="formactions"><button type="button" class="btn secondary" onclick="loanStage=2;render()">Back</button><button class="btn" type="submit">Review agreement ${icon('chevron')}</button></div></form>`;
if(loanStage===4)body=`<div class="panel-head"><div><span class="eyebrow muted">Loan documentation</span><h2 style="margin-top:7px">Read before you sign.</h2></div><button class="textbtn" onclick="downloadAgreement()" aria-label="Download sample agreement">${icon('download')}</button></div><div class="document" tabindex="0" aria-label="Sample loan agreement">${agreementHTML()}</div><form id="loan-agreement" class="stack" style="margin-top:22px"><label class="check"><input type="checkbox" required><span>I have read the sample agreement, including the fee, repayment obligations and demo-only status.</span></label><label class="check"><input type="checkbox" required><span>I agree to proceed with a simulated electronic signature. This does not create a binding agreement.</span></label><div class="formactions"><button type="button" class="btn secondary" onclick="loanStage=3;render()">Back</button><button class="btn" type="submit">Continue to signing ${icon('lock')}</button></div></form>`;
if(loanStage===5)body=`<div class="panel-head"><h2>Your final step.</h2><div class="roundicon">${icon('lock')}</div></div><p class="muted" style="margin-bottom:22px">Confirm your name and approve the sample agreement.</p><div class="loan-offer"><span class="eyebrow muted">Agreement summary</span><div class="summary-line"><span>Borrower</span><strong>${esc(state.name)}</strong></div><div class="summary-line"><span>Loan amount</span><strong>${money(loan.amount)}</strong></div><div class="summary-line"><span>Monthly instalment</span><strong>${money(c.payment)}</strong></div><div class="summary-line"><span>Net disbursement</span><strong>${money(c.net)}</strong></div></div><form id="loan-sign" class="stack" style="margin-top:22px"><label>Type your full name<input name="signature" required autocomplete="off" placeholder="${esc(state.name)}"></label><div class="notice">No signing service is connected and no SMS was sent. Enter demo code <strong>123456</strong>.</div><label>Demo signing code<input name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required placeholder="6-digit code"></label><label class="check"><input type="checkbox" required><span>I authorize this demo signature and the credit of fictional funds to my demo account.</span></label><div id="form-error" class="error hidden" role="alert"></div><div class="formactions"><button type="button" class="btn secondary" onclick="loanStage=4;render()">Back</button><button class="btn" type="submit">Sign & complete demo ${icon('check')}</button></div></form>`;
if(loanStage===6){const l=state.loans.at(-1);body=`<div class="success"><div class="success-icon">${icon('check')}</div><span class="pill">Demo loan disbursed</span><h2 style="margin-top:15px">Your next chapter is ready.</h2><p>Your sample agreement has been signed and ${money(l.net)} in fictional funds has been added to your everyday account.</p></div><div class="summary-line"><span>Demo loan reference</span><strong>${l.id}</strong></div><div class="summary-line"><span>Monthly instalment</span><strong>${money(l.payment)}</strong></div><div class="summary-line"><span>First repayment</span><strong>${dateText(l.firstDate)}</strong></div><div class="summary-line"><span>Updated account balance</span><strong>${money(state.balance)}</strong></div><div class="summary-line"><span>Sample signature</span><strong>${esc(l.signedBy)}</strong></div><div class="notice" style="margin-top:18px">Completed entirely in this demo. No money moved and no legally binding signature was created.</div><div class="formactions"><button class="btn secondary" onclick="downloadAgreement(true)">${icon('download')} Agreement</button><button class="btn" onclick="goto('dashboard')">View my account ${icon('chevron')}</button></div>`}
return `${pagehead('A loan for your next chapter.','From application to agreement — a simple, transparent journey.')} ${loanSteps()}<div class="two-col"><section class="panel">${body}</section><aside class="stack">${loanSummary()}<section class="panel insight"><div class="row">${icon('shield')}<h3>You’re in control</h3></div><p style="margin-bottom:0">Review every term before signing. All offers, decisions, signatures and funds are fictional.</p></section></aside></div>`}
function activeLoans(){return `<div class="divider"></div><h3 style="margin-bottom:12px">Your completed demo loans</h3>${state.loans.map(l=>`<div class="summary-line"><span>${l.id}<br>${money(l.amount)} · ${l.months} months</span><strong>${money(l.payment)} / month<br><span class="pill">Disbursed</span></strong></div>`).join('')}`}
function schedule(){let balance=Number(loan.amount);const c=loanCalc(),r=.069/12;let rows='';for(let i=1;i<=loan.months;i++){const interest=balance*r,payment=i===Number(loan.months)?balance+interest:c.payment,principal=payment-interest;balance=Math.max(0,balance-principal);rows+=`<tr><td>${i}</td><td>${money(payment)}</td><td>${money(principal)}</td><td>${money(interest)}</td><td>${money(balance)}</td></tr>`}return `<div class="scrolltable"><table class="schedule"><thead><tr><th>Month</th><th>Payment</th><th>Principal</th><th>Interest</th><th>Balance</th></tr></thead><tbody>${rows}</tbody></table></div>`}
function agreementHTML(l=loan,signed=null){const c=loanCalc(l);return `<h3>BIMI · SAMPLE PERSONAL LOAN AGREEMENT</h3><p><strong>DEMONSTRATION ONLY — NON-BINDING</strong><br>Version DEMO-1.0 · ${localDate()}</p><p>This is fictional product content for evaluating a digital journey. Bimi is a concept, not a bank. It is not a ProCredit Bank document and cannot be used to obtain credit.</p><h3>1. Parties and purpose</h3><p>Demo borrower: ${esc(state.name)}. Purpose: ${esc(l.purpose)}. All personal details and funds must be fictional.</p><h3>2. Loan and disbursement</h3><p>Principal: ${money(l.amount)}. Term: ${l.months} months. A one-time fee of ${money(c.fee)} (1%) is deducted from the principal. The net demo credit to the account is ${money(c.net)}.</p><h3>3. Interest and costs</h3><p>Fixed nominal annual interest: 6.90%. Illustrative effective annual rate: ${c.apr.toFixed(2)}%. Monthly instalment: approximately ${money(c.payment)}. Total instalments: ${money(c.total)}. Total borrowing cost: ${money(c.cost)}, comprising interest of ${money(c.interest)} and the fee. No insurance or other charges are assumed.</p><h3>4. Repayment</h3><p>There are ${l.months} monthly instalments. The first demo repayment is one month after the simulated signing date. Equal monthly periods are assumed. The final instalment may be adjusted for rounding. No automatic debit occurs in this prototype.</p><h3>5. Customer rights and servicing</h3><p>A production agreement must define applicable withdrawal and early repayment rights, complaints, late payment terms and servicing procedures using bank-approved legal wording. This sample does not establish those terms or replace required disclosures.</p><h3>6. Electronic approval</h3><p>The typed name and fixed demonstration code simulate agreement acceptance. They do not constitute a verified or legally binding electronic signature. Production signing requires an approved provider and an appropriate evidence and document-retention process.</p><h3>7. Data and legal status</h3><p>Demo account and transaction state is held in this browser session. No customer data is submitted to a bank. No identity, credit or AML checks are performed. This sample requires legal and compliance review before any real-world use.</p>${signed?`<h3>Demo acceptance record</h3><p>Reference: ${esc(signed.id)}<br>Typed name: ${esc(signed.signedBy)}<br>Timestamp: ${esc(signed.signedAt)}<br>Method: fixed demo code. This is not cryptographic proof of identity.</p>`:''}`}
function baseDownloadAgreement(signed=false){const l=signed?state.loans.at(-1):loan;const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>Bimi Sample Loan Agreement</title><style>body{font:15px/1.7 Georgia,serif;max-width:800px;margin:45px auto;padding:20px;color:#24362c}h3{color:#143e36}button{padding:10px 20px;margin-bottom:20px}@media print{button{display:none}}</style><button onclick="print()">Print / Save as PDF</button>${agreementHTML(l,signed?l:null)}</html>`;download('Bimi_Demo_Loan_Agreement.html',html,'text/html')}

// Source: src/features/activity-base.js
function baseActivity(){return `${pagehead('Every movement, in view.','Review your demo payments and account activity.',`<button class="btn secondary" onclick="statement()">${icon('download')} Export CSV</button>`)}<section class="panel"><div class="panel-head"><h2>Account activity</h2><input class="filter-input" type="search" id="tx-search" placeholder="Search transactions" aria-label="Search transactions"></div><div id="all-transactions">${txRows(state.tx)}</div></section><div class="notice" style="margin-top:20px">Demo state is kept for this browser session. <button class="textbtn" style="font-size:12px;padding:0" onclick="resetDemo()">Reset demo data</button></div>`}
function resetDemo(){if(confirm('Reset all fictional balances, cards, transfers and loans?')){state=seed();save();loanStage=0;loan={amount:10000,months:36,purpose:'Home improvement',income:1850,commitments:200,employment:'Employed',docs:false};registeredCredentials=null;goto('dashboard');toast('Demo reset to the sample customer.')}}
function statement(){const cell=v=>'"'+String(v).replace(/"/g,'""')+'"';download('Bimi_Demo_Statement.csv','DEMO ONLY - NOT A BANK STATEMENT\n'+[['Date','Reference','Description','Amount EUR'],...state.tx.map(t=>[t.date,t.id,t.name,t.amount.toFixed(2)])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');toast('Demo statement downloaded.')}
function baseBind(){const bindForm=(id,fn)=>{const f=$(id);if(f)f.addEventListener('submit',e=>{e.preventDefault();fn(new FormData(f))})};
bindForm('#login-form',d=>{const email=String(d.get('email')).toLowerCase().trim(),pw=d.get('password');if((email==='demo@bimi.test'&&pw==='Bimi2026!')||(registeredCredentials&&email===registeredCredentials.email&&pw===registeredCredentials.password)){if(email==='demo@bimi.test'&&state.email!=='demo@bimi.test'){state=seed();save()}registeredCredentials=null;enterDemo()}else error('Use demo@bimi.test and Bimi2026!, or the profile you registered during this visit.')});
bindForm('#register-form',d=>{registration={name:(d.get('first').trim()+' '+d.get('last').trim()).trim(),email:d.get('email').trim().toLowerCase(),phone:d.get('phone').trim()};if(!d.get('first').trim()||!d.get('last').trim())return error('Enter a first and last name.');registeredCredentials={email:registration.email,password:d.get('password')};authStep=1;render()});
bindForm('#register-verify',d=>{if(d.get('code')!=='123456')return error('Use the demo verification code 123456.');state=seed();state.name=registration.name;state.email=registration.email;save();enterDemo();toast('Temporary demo profile activated. No real account was opened.')});
bindForm('#transfer-form',d=>{const amount=Number(d.get('amount')),fee=d.get('type')==='Domestic transfer'?.5:0,iban=d.get('iban').replace(/\s/g,'').toUpperCase(),name=d.get('name').trim();if(!name)return error('Enter the recipient name.');if(!/^XK\d{18}$/.test(iban))return error('Use an XK demo IBAN with 18 digits after XK. Example: XK050000000000000001.');if(iban==='XK050000000000000000')return error('Choose a recipient account different from your own.');if(!Number.isFinite(amount)||amount<=0||amount>10000)return error('Enter an amount between €0.01 and the €10,000 demo limit.');if(amount+fee>state.balance)return error('Insufficient demo balance to cover the amount and fee.');transfer={name,iban,amount,fee,type:d.get('type'),note:d.get('note').trim()};transferStage=1;render()});
if($('#transfer-form')&&transfer){const f=$('#transfer-form');for(const k of ['name','iban','amount','type','note'])f.elements[k].value=transfer[k]}
bindForm('#transfer-confirm',d=>{if(d.get('code')!=='123456')return error('Use demo approval code 123456.');if(transferStage!==2||!transfer)return;if(transfer.amount+transfer.fee>state.balance)return error('Insufficient demo balance.');transfer.id=reference('TRF');state.balance=Math.round((state.balance-transfer.amount-transfer.fee)*100)/100;state.tx.unshift({id:transfer.id,name:transfer.name,desc:transfer.type+' · '+(transfer.note||'Personal transfer'),amount:-transfer.amount,date:localDate(),kind:'out'});if(transfer.fee)state.tx.splice(1,0,{id:transfer.id+'-FEE',name:'Transfer fee',desc:transfer.id,amount:-transfer.fee,date:localDate(),kind:'out'});save();transferStage=3;render();toast('Demo transfer completed.')});
bindForm('#card-limits',d=>{for(const k of ['atm','pos','web']){const v=Number(d.get(k));if(!Number.isInteger(v)||v<0||v>10000)return error('Limits must be whole euros between 0 and 10,000.')}for(const k of ['atm','pos','web'])state.card[k]=Number(d.get(k));save();render();toast('Daily card limits saved for this demo session.')});
bindForm('#loan-application',d=>{const a=Number(d.get('amount')),m=Number(d.get('months')),income=Number(d.get('income')),debts=Number(d.get('commitments'));if(!Number.isFinite(a)||a<500||a>30000||a%100!==0)return error('Choose €500–€30,000 in increments of €100.');if(![12,24,36,48,60,72,84].includes(m)||!Number.isFinite(income)||income<=0||!Number.isFinite(debts)||debts<0)return error('Check the loan term, income and existing debt payments.');loan={...loan,amount:a,months:m,income,commitments:debts,purpose:d.get('purpose'),employment:d.get('employment')};loanStage=1;render();window.scrollTo(0,0)});
for(const id of ['#loan-amount','#loan-months'])if($(id))$(id).addEventListener('input',()=>{const a=Number($('#loan-amount').value),m=Number($('#loan-months').value);if(a>=500&&a<=30000){loan.amount=a;loan.months=m;const c=loanCalc();$('#summary-payment').innerHTML=money(c.payment)+'<span style="font-size:12px;font-weight:400;letter-spacing:0"> / month</span>';for(const [key,value]of Object.entries({amount:money(a),term:m+' months',apr:c.apr.toFixed(2)+'%',fee:money(c.fee),net:money(c.net),total:money(c.total),cost:money(c.cost)}))$('#summary-'+key).textContent=value;}});
bindForm('#loan-documents',()=>{loan.docs=true;loanStage=2;render();window.scrollTo(0,0)});
bindForm('#loan-offer',()=>{loanStage=4;render();window.scrollTo(0,0)});
bindForm('#loan-agreement',()=>{loanStage=5;render();window.scrollTo(0,0)});
bindForm('#loan-sign',d=>{if(loanStage!==5)return;if(d.get('signature').trim().toLowerCase()!==state.name.toLowerCase())return error('Type your full demo profile name: '+state.name);if(d.get('code')!=='123456')return error('Use the demo signing code 123456.');const c=loanCalc();if(c.ratio>40||!loan.docs)return error('Complete the demo assessment before signing.');const first=new Date();const day=first.getDate();first.setDate(1);first.setMonth(first.getMonth()+1);first.setDate(Math.min(day,new Date(first.getFullYear(),first.getMonth()+1,0).getDate()));const l={...loan,...c,id:reference('LN'),signedBy:state.name,signedAt:new Date().toISOString(),firstDate:`${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(first.getDate()).padStart(2,'0')}`};state.loans.push(l);state.balance=Math.round((state.balance+c.net)*100)/100;state.tx.unshift({id:l.id,name:'Personal loan disbursement',desc:'Demo funds · fee deducted: '+money(c.fee),amount:c.net,date:localDate(),kind:'in'});save();loanStage=6;render();window.scrollTo(0,0);toast('Demo agreement signed and fictional funds credited.')});
if($('#tx-search'))$('#tx-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#all-transactions').innerHTML=txRows(state.tx.filter(t=>(t.name+' '+t.desc+' '+t.id).toLowerCase().includes(q)))});
}

